/*
 * A371280  Irregular triangular array of denominators of the set T of
 *          fractions generated by these rules: g(1) = (1), and if x and y are
 *          in T, then x/(y+1) is in T; see Comments.
 * https://oeis.org/A371280
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf, frac
 * Formula:   a(n) = denominator of the n‑th fraction generated by the rule
 *            x/(y+1) starting with the single fraction 1/1. The fractions are
 *            produced breadth‑first: at each generation all pairs of the
 *            already generated fractions are combined in the order i=1..m,
 *            j=1..m; new fractions that have appeared before...
 * Range:     u8 n <= 71, u16 n <= 71, u32 n <= 71, u64 n <= 71, u128 n <= 71,
 *            big any n
 * Helpers:   gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The following implementation maintains the list of all fractions
   produced so far, the set of fractions already seen, and expands the
   list until it contains at least n elements.  The long division
   operators of seq_t are assumed to be overloaded for the arbitrary‑
   precision case.  The code is compatible with both C11 and C++17. */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include "../utils/gcd.h"

/* --- Fraction type ----------------------------------------------------- */
typedef struct {
    seq_t num;
    seq_t den;
} fraction_t;

/* --- Storage for all fractions ------------------------------------------ */
static fraction_t *fractions = NULL;   /* array of fractions          */
static size_t      cap      = 0;        /* capacity of the array       */
static size_t      len      = 0;        /* number of fractions stored */

/* --- Hash table for detecting duplicates ------------------------------- */
#define HASH_BITS 16
#define HASH_SIZE (1U << HASH_BITS)
#define HASH_MASK (HASH_SIZE - 1)

static int hash_table[HASH_SIZE]; /* indices of fractions, -1 = empty */
static bool hash_inited = false;

/* Simple hash from a numerator/denominator pair. */
static size_t hash_frac(seq_t num, seq_t den)
{
    uint64_t a = (uint64_t)num;
    uint64_t b = (uint64_t)den;
    return (size_t)((a ^ (b << 1)) & HASH_MASK);
}

/* Insert a fraction into the hash table if it is not already present.
   Returns 1 if inserted, 0 if it already existed. */
static int hash_insert_unique(seq_t num, seq_t den, size_t idx)
{
    size_t h = hash_frac(num, den);
    for (;;) {
        int pos = (int)h;
        if (hash_table[pos] == -1) {
            hash_table[pos] = (int)idx;      /* store index of fraction */
            return 1;                       /* inserted */
        }
        /* Compare contents to check for equality */
        size_t existing_idx = (size_t)hash_table[pos];
        if (fractions[existing_idx].num == num &&
            fractions[existing_idx].den == den)
            return 0;                       /* duplicate */
        h = (h + 1) & HASH_MASK;             /* linear probing */
    }
}

/* Grow the fraction array when needed. */
static void grow_fractions(void)
{
    size_t new_cap = cap ? cap * 2U : 64U;
    fraction_t *tmp = (fraction_t *)realloc(fractions, new_cap * sizeof(fraction_t));
    if (!tmp) abort();
    fractions = tmp;
    cap = new_cap;
}

/* Initialise static state on the first call. */
static void init_static(void)
{
    if (hash_inited) return;
    /* -1 sentinel for empty hash slots */
    for (int i = 0; i < HASH_SIZE; ++i) hash_table[i] = -1;
    cap = 64U;
    fractions = (fraction_t *)malloc(cap * sizeof(fraction_t));
    if (!fractions) abort();
    len = 0;
    /* Insert the starting fraction 1/1 */
    fractions[0].num = (seq_t)1;
    fractions[0].den = (seq_t)1;
    hash_insert_unique((seq_t)1, (seq_t)1, 0);
    len = 1;
    hash_inited = true;
}

/* ----------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n < 1) return (seq_t)0;  /* undefined for n < 1 */

    init_static();

    /* If we already have enough terms, return immediately. */
    if ((idx_t)len >= n) return fractions[n - 1].den;

    /* Generate new generations until we reach at least n terms. */
    while ((idx_t)len < n) {
        size_t old_len = len;  /* size before this generation */

        for (size_t i = 0; i < old_len; ++i) {
            seq_t num_i = fractions[i].num;
            seq_t den_i = fractions[i].den;

            for (size_t j = 0; j < old_len; ++j) {
                seq_t num_j = fractions[j].num;
                seq_t den_j = fractions[j].den;

                /* New fraction: num_i / (1 + num_j/den_j) */
                seq_t num = num_i * den_j;
                seq_t den = den_i * (num_j + den_j);
                seq_t g   = gcd(num, den);

                if (g > (seq_t)1) {         /* reduce fraction */
                    num /= g;
                    den /= g;
                }

                if (hash_insert_unique(num, den, len)) {
                    if (len >= cap) grow_fractions();
                    fractions[len].num = num;
                    fractions[len].den = den;
                    ++len;
                }
            }
        }
    }

    return fractions[n - 1].den;
}
